function validate(input) {
  const [{ Schools = [], Exam = [] }] = input;
  const schools = new Set(), scores = new Set();
  for (const [id, capacity] of Schools) {
    if (id === null || capacity === null) return 'Every school needs a school_id and a capacity.';
    if (schools.has(id)) return `school_id ${id} appears twice.`;
    if (capacity < 0) return `School ${id} has a negative capacity.`;
    schools.add(id);
  }
  for (const [score, count] of Exam) {
    if (score === null || count === null) return 'Every exam row needs a score and a student_count.';
    if (scores.has(score)) return `score ${score} appears twice.`;
    if (count < 0) return `score ${score} has a negative student_count.`;
    scores.add(score);
  }
  const sorted = [...Exam].sort((a, b) => b[0] - a[0]);
  for (let i = 1; i < sorted.length; i++) {
    if (sorted[i][1] < sorted[i - 1][1]) return `score ${sorted[i][0]} has fewer students than the higher score ${sorted[i - 1][0]}.`;
  }
  return null;
}

