function generate(rand, size) {
  const small = size === 'small';
  const examRows = small ? Math.floor(rand() * 7) : 600;
  const schoolRows = small ? Math.floor(rand() * 7) : 800;
  // Distinct scores, highest first; counts never shrink as the score drops, and often repeat.
  const pool = [];
  for (let s = small ? 500 : 0; s <= 1000; s += small ? 25 : 1) pool.push(s);
  for (let i = pool.length - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [pool[i], pool[j]] = [pool[j], pool[i]]; }
  const chosen = pool.slice(0, examRows).sort((a, b) => b - a);
  const steps = small ? [0, 0, 5, 12, 30] : [0, 0, 1, 3, 8, 20];
  const Exam = [], counts = [];
  let count = 1 + Math.floor(rand() * (small ? 15 : 5));
  for (const score of chosen) {
    Exam.push([score, count]);
    counts.push(count);
    count += steps[Math.floor(rand() * steps.length)];
  }
  // Capacities land on, just below and just above existing counts, and outside their range.
  const top = counts.length ? counts[counts.length - 1] : 20;
  const Schools = [];
  const ids = [];
  for (let id = 1; id <= (small ? 12 : 1200); id++) ids.push(id);
  for (let i = ids.length - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [ids[i], ids[j]] = [ids[j], ids[i]]; }
  for (const id of ids.slice(0, schoolRows)) {
    const r = rand();
    let capacity;
    if (counts.length && r < 0.6) capacity = counts[Math.floor(rand() * counts.length)] + [-1, 0, 0, 1][Math.floor(rand() * 4)];
    else capacity = Math.floor(rand() * (top + 10));
    Schools.push([id, Math.max(0, capacity)]);
  }
  return [{ Schools, Exam }];
}
